function votesOf(c){return c.base+(S.myVotes.includes(c.id)?1:0)}
function composite(c){const mx=Math.max(...CH.map(votesOf));return 0.4*votesOf(c)/mx*100+0.3*c.impact+0.2*c.dq+0.1*c.feas}
function ranked(){return [...CH].sort((a,b)=>composite(b)-composite(a))}
