<div class="grid g4">${BEN.map(b=>`<div class="panel stack"><span class="icbox">${ico(b[0],24)}</span><h3>${A(b[1],b[2])}</h3><p class="small muted">${A(b[3],b[4])}</p></div>`).join("")}</div>
