<div class="utabs">${DASHPREV.map(k=>`<button class="utab ${k===dp?"on":""}" data-act="dp" data-k="${k}"><span class="ic">${ico(UT.find(u=>u.k===k).i,20)}</span>${roleName(k)}</button>`).join("")}</div>
