function cityM(k){const d=CDATA[k];if(!d)return {participants:6840,inputs:2140,approved:10,teams:40,research:80,launched:20,jobs:120,cumV:60,cumJ:360,cumT:360,cumR:720,women:0.41,month:9,sim:false};
 return Object.assign({approved:10,teams:40,research:80,launched:20,cumV:60,cumT:360,cumR:720,month:9,sim:true},d.m,{cumJ:d.m.jobs*3})}
let CURK=null,LOCMAP=[];
function LOC(h){for(const [a,b] of LOCMAP)h=h.split(a).join(b);return h}
function applyCity(){const c=curCity();if(c.k===CURK)return;CURK=c.k;IRB=cityM(c.k);
 if(c.k==="irbid"||!CDATA[c.k]){({DIST,CH,UNIS,PEOPLE,ORGS,PROJ,LAUNCHED}=IRB0);LOCMAP=[];return}
 const d=CDATA[c.k],ci=CITIES.indexOf(c)+1,nm=c.n;DIST=d.dist;
 const lines=RAW.split("\n").map(l=>l.split("|"));SIGIDX.forEach((ix,j)=>{lines[ix]=d.sig[j]});
 CH=lines.map(([ar,en,s,dd],i)=>{const boost=(c.sec.includes(s)?1.6:1)*(SIGIDX.includes(i)?1.5:1);const r=(k)=>rnd(i+ci*53,k);return{id:"c"+String(i+1).padStart(2,"0"),t:[ar,en],s,d:dd,
  base:Math.round((80+r(1)*560)*boost),impact:Math.round(55+r(2)*42),dq:Math.round(50+r(3)*48),feas:Math.round(45+r(4)*50),inputs:Math.round((6+r(5)*70)*IRB.inputs/2140),dup:Math.round(r(6)*9)}});
 UNIS=[["جامعة حكومية (أ) – "+nm[0],"Public University A – "+nm[1]],["جامعة علوم وتكنولوجيا (ب) – "+nm[0],"Science & Tech University B – "+nm[1]],["جامعة خاصة (ج) – "+nm[0],"Private University C – "+nm[1]],["كلية تقنية (د) – "+nm[0],"Technical College D – "+nm[1]]];
 const map={};IRB0.PEOPLE.forEach((p,i)=>{map[p[0]]=d.ppl[i];map[p[1]]=d.ppl[i]});
 const lg=d.lang==="ar"?["ar","en"]:[d.lang,"en"];
 PEOPLE=IRB0.PEOPLE.map((p,i)=>[d.ppl[i][0],d.ppl[i][1],p[2],i%3===0?lg.concat(d.lang==="ar"?["fr"]:["ar"]):lg,p[4],p[5]]);
 LOCMAP=[];IRB0.PEOPLE.forEach((p,i)=>{LOCMAP.push([p[0],d.ppl[i][0]],[p[1],d.ppl[i][1]])});LOCMAP.push(["شارع الجامعة","الطرق الرئيسية"],["University Street","main roads"]);
 const sw=n=>map[n[0]]||n;PROJ=IRB0.PROJ.map(p=>Object.assign({},p,{pm:sw(p.pm),co:sw(p.co),rap:sw(p.rap)}));
 ORGS=IRB0.ORGS.map(o=>o[2]==="chamber"?[d.ch[0]+" (المضيف)",d.ch[1]+" (host)","chamber",true]:o);
 LAUNCHED=IRB0.LAUNCHED.map((l,i)=>i===1?Object.assign({},l,{v:["دكّان أونلاين","Dukkan Online"],c:"c30"}):l)}
const CNAME=()=>L(curCity().n);
function cityVals(c){const s=c.sec.map(sectName);return [A(`ربط جامعات ${c.n[0]} بتحديات ${s[0]} و${s[1]}`,`Link ${c.n[1]}'s universities to ${s[0]} and ${s[1]} challenges`),A(`مشاريع ريادية في ${s[2]} و${s[3]} بمشاركة الشركات المحلية`,`Ventures in ${s[2]} and ${s[3]} with local companies on the team`),A("40 فريقاً و20 مشروعاً شهرياً عند النضج","40 teams and 20 ventures a month at maturity"),A("100 وظيفة شهرياً على الأقل للشباب والنساء","At least 100 jobs a month for youth and women")]}
function citySelect(id){return `<label class="row small" for="${id}" style="gap:8px"><b>${A("المدينة","City")}</b><select class="sel" id="${id}" data-act="city">${[1,2,3].map(p=>`<optgroup label="${PHN(p)}">${CITIES.filter(c=>c.ph===p).map(c=>`<option value="${c.k}" ${c.k===curCity().k?"selected":""}>${L(c.n)} — ${L(c.c)}</option>`).join("")}</optgroup>`).join("")}</select></label>`}
function cityPanel(){const c=curCity();const M=IRB;const r=ranked();return `<div class="panel stack"><div class="between">${citySelect("citySelPub")}<span class="chip ${STC(c.st)}">${STN(c.st)} · ${PHN(c.ph)}</span></div>
<div class="grid g2"><div class="stack"><h3 style="font-size:24px">${L(c.n)} <span class="muted small">${L(c.c)}</span></h3><p>${L(c.ctx)}</p>${c.fact?`<p class="tiny muted">${L(c.fact)}</p>`:""}<div class="row">${c.sec.map(s=>`<span class="chip">${sectName(s)}</span>`).join("")}</div><p class="tiny muted">${A("الجهة المضيفة: ","Host: ")}${L(ORGS.find(o=>o[2]==="chamber")).replace(/ \((المضيف|host)\)/,"")} · ${A("المناطق: ","Districts: ")}${Object.values(DIST).slice(0,5).map(L).join(A("، ",", "))}</p></div>
<ul class="clean stack">${cityVals(c).map(v=>`<li class="row" style="gap:10px;align-items:flex-start"><span class="chip good">✓</span><span>${v}</span></li>`).join("")}</ul></div>
<div class="cycle">${STEPS.map((s,i)=>`<div class="step ${i===3?"now":""}"><span class="no">${fmt(i+1)}</span><b class="small">${L(s)}</b></div>`).join("")}</div>
<div class="grid g4">${kpi(fmt(M.inputs),A("مدخلاً هذا الشهر","inputs this month"))}${kpi(A("10 من 50","10 of 50"),A("تحديات معتمدة","approved challenges"))}${kpi(fmt(M.teams),A("فريقاً تشكّل هذا الشهر","teams formed this month"))}${kpi(fmt(M.research),A("بحثاً علمياً بدأ هذا الشهر","research projects started"))}${kpi(fmt(M.launched),A("مشروعاً أُطلق هذا الشهر","ventures launched this month"))}${kpi(fmt(M.jobs),A("وظيفة مباشرة هذا الشهر","direct jobs this month"),"var(--gold)")}${kpi(fmt(M.cumJ),A("وظيفة منذ الانطلاق","jobs since launch"))}${kpi(pct(M.women),A("نسبة النساء","women share"))}</div>
<div class="stack" style="gap:6px"><b class="small">${A("أعلى 3 تحديات في "+L(c.n)+" هذا الشهر","Top 3 challenges in "+L(c.n)+" this month")}</b>${r.slice(0,3).map((x,i)=>`<div class="between small" style="border-bottom:1px solid var(--line);padding:4px 0;gap:8px"><span><span class="chip gold">#${fmt(i+1)}</span> ${esc(L(x.t))} <span class="tiny muted">· ${L(DIST[x.d])}</span></span><span class="tiny muted" style="white-space:nowrap">${fmt(votesOf(x))} ${t("votes")}</span></div>`).join("")}</div>
<p class="tiny muted">${M.sim?A("محاكاة افتراضية لدورة العمل في المدينة (الشهر "+M.month+" من التشغيل المتوقع) — بيانات أولية لحين انطلاقها الفعلي.","Simulated work cycle for the city (month "+M.month+" of expected operations) — preliminary data until it goes live."):A("الشهر "+M.month+" من التشغيل · بيانات تجريبية","Month "+M.month+" of operations · demo data")}</p></div>`}
